import json,html
from urllib.parse import quote
P=Path(__file__).parent
E=html.escape
base='https://github.com/undralg/Data-Science-Projects/blob/main/'
projects=[]
def add(slug,title,category,tags,question,method,finding,limit,links,metric='',label='',role='Independent analysis',chart=None):
 projects.append(dict(slug=slug,title=title,category=category,tags=tags,question=question,method=method,finding=finding,limit=limit,links=links,metric=metric,label=label,role=role,chart=chart))
add('dna-inference','Inferring family relationships from DNA',['Statistics & ML'],['Bayesian inference','R','Simulation','Genetics'],'How can we assess distant kinship when only limited relatives are available?','Developed an Approximate Bayesian Computation pipeline that simulates DNA-sharing patterns under competing pedigree hypotheses, summarizes shared segments and estimates support for related versus unrelated models. The capstone examines 11 pedigrees and includes repeated cross-validation and label-permutation checks.','The framework makes the relationship hypothesis, reference populations and uncertainty explicit. It was motivated by humanitarian identification work in Argentina, where ambiguous genetic evidence has consequences for families.','Internal cross-validation measures performance within the constructed reference banks. It is not a real-world identification accuracy estimate, and should not be directly compared with STR detection power as though the metrics were interchangeable.', [('Read capstone paper','https://docs.google.com/document/d/1e9A9l0uKJ8IvY67Jtgu8liAjk33Njx_lanUBgxBzeTs/edit'),('Explore early notebooks','https://github.com/undralg/ABC-inference-public'),('mispitools contributor credits','https://github.com/MarsicoFL/mispitools#authors')],'11','pedigrees examined','Capstone research · Institute of Calculus, University of Buenos Aires')
add('vinyl','Vinyl beyond release week',['Market Research','Statistics & ML'],['R','Tableau','Regression','Web data collection'],'Streaming made physical albums optional. Why did vinyl grow while CDs declined?','Combined RIAA market trends, publicly reported album sales and industry catalog breakdowns.','Older recordings account for a larger share of vinyl purchases than CD purchases.','','', '132','albums in the opening-week dataset')
projects[-1]['links']=[]
add('huzur','Huzur: AI with hidden information',['Software & AI'],['JavaScript','Python','Cloudflare','Game AI'],'Can an AI opponent play a traditional Mongolian card game without seeing the other players’ cards?','Built a browser game for 2–5 players, with local human and AI seats, multiplayer lobbies and persistent match records. AI decisions combine strategic heuristics, lookahead and exact two-player endgame search. Offline self-play supports policy comparisons.','The project connects a playable product with an evaluation loop: log decisions, simulate opponents, compare policies and revise the strategy. Fairness guards keep hidden opponent cards and deck order out of bot decision inputs.','Simulated match results do not establish performance against human players. The documented multiplayer roadmap still includes server-side rules validation.',['PLACEHOLDER'],'2–5','players supported','Independent software project')
projects[-1]['links']=[('Play Huzur','https://huzur-card-game-platform.undral.workers.dev/'),('View code',base.replace('/blob/','/tree/')+'card-game-platform')]
add('causal-inference','Finding a credible comparison',['Statistics & ML'],['Causal inference','R','Matching','Synthetic control'],'How much does the choice of comparison group change an estimated effect?','Analyzed job-training outcomes using experimental and observational data, propensity-score and genetic matching, and instrumental variables. A second application uses synthetic control and placebo diagnostics to examine California’s 2011–2015 drought and crime.','The job-training exercise illustrates why treatment selection matters: a naive observational comparison can reverse the direction of the randomized comparison. Matching is assessed against the experimental benchmark; the drought analysis makes the counterfactual and placebo evidence explicit.','These are course analyses, not new randomized experiments. Causal interpretations depend on balance, identification assumptions and the credibility of the comparison group.',[('View notebook',base+'Causal%20Inference.ipynb')],role='Individual course project')
add('bayesian-housing','Pricing homes when outliers matter',['Statistics & ML'],['Bayesian inference','Regression','Model comparison'],'How sensitive is a housing model to unusual properties and heavy-tailed errors?','Compared Normal, Student-t and outlier-aware Bayesian regression specifications for Buenos Aires property pricing.','Treating the likelihood as a modeling decision makes the influence of unusual observations visible. The report compares specifications rather than relying on a single error model.','Results describe the project dataset and modeling assumptions; they are not a deployed appraisal system.',[('Read report',base+'BA%20Real%20Estate/Bayesian%20Regression%20for%20Real%20Estate%20Pricing%20in%20Buenos%20Aires%20(1).pdf'),('View notebook',base+'BA%20Real%20Estate/bayesian_regression_real_estate_BA_code.ipynb')],role='Individual course project')
add('social-networks','Modeling social isolation',['Statistics & ML'],['Simulation','Networks','Monte Carlo'],'What happens when social isolation and algorithmic exposure reinforce each other?','Built an agent-based Monte Carlo simulation on weighted friendship networks. Isolation, exposure, ideological drift and friendship decay interact; intervention scenarios change amplification and social support.','The model provides a way to explore feedback loops and compare interventions under a common set of assumptions. Network dynamics reveal behavior that a static average would hide.','These are simulated outcomes. The model does not establish empirical causal effects of recommendation systems or real interventions.',[('Read report',base+'male-loneliness-epidemic-simulation/CS166_final_report_with_figures.pdf'),('View notebook',base+'male-loneliness-epidemic-simulation/CS166_final_codebook.ipynb')],role='Course simulation project')
add('multilevel-scores','Recovering distributions from histograms',['Statistics & ML'],['Hierarchical modeling','Partial pooling','Bayesian inference'],'Can we compare student cohorts when their score histograms use different bins?','Modeled latent test-score distributions from grouped observations, comparing pooling choices across years while retaining the information represented by each histogram bin.','The analysis tackles a common practical problem: the raw records are unavailable, yet a comparison is still needed. Probabilistic modeling expresses uncertainty instead of pretending the bin midpoints are individual observations.','The conclusions depend on distributional assumptions and the information retained in the published histograms.',[('View notebook',base+'Discrete%20and%20multi-level%20models.ipynb')],role='Course modeling project')
add('movie-preferences','Do more modalities mean better predictions?',['Statistics & ML'],['Machine learning','Python','PCA','Multimodal modeling'],'Do movie posters and text add useful signal beyond structured metadata?','Aligned 568 titles from 615 collected IMDb ratings. Compared 36 metadata features with ResNet-50 poster embeddings and TF-IDF/SVD text representations using dimensionality reduction, classification and modality ablations.','The exploratory run suggested that adding high-dimensional poster and text features did not automatically improve on metadata. The public notebook replaces the primary comparison with fold-local preprocessing pipelines.','The original evaluation fitted preprocessing before the train/test split. A leakage-free rerun is still needed; historical performance estimates are not presented as validated generalization results.',[('Read project and notebook',base.replace('/blob/','/tree/')+'multimodal-movie-preference-modeling')],'568','aligned movie titles','Exploratory course project')
add('forum','Forum AI Notetaker',['Software & AI'],['Python','Flask','SQL','SQLite','React','Transcription','Testing'],'How can class recordings become searchable transcripts and useful notes?','Worked on a team-built course platform that connects recording uploads, FFmpeg audio extraction, Whisper transcription and AI-generated summaries, topics and action items. The application uses Flask, React and SQLite, with course membership controlling access.','The platform brings recordings, transcripts and notes into one searchable workflow. My contribution focused on the relational database and data-integrity testing. The project includes session-processing states and preserves transcripts when note generation fails.','Team course project, not a claim of sole authorship. The public repository documents the implementation and setup; the linked video demonstrates the application.', [('View repository','https://github.com/islamborghini/forum-ai-notetaker'),('Watch demo','https://drive.google.com/file/d/11JSakbIamDS8JBap28sZX6Nz741hunM5/view')],role='Team software project')
f=json.loads((P/'finance_sources.json').read_text())
def finance(i,slug,title,tags,q,m,result,limit,chart=None):
 links=[('Read analysis',f[i]['url']),('Open financial model',f[i]['spreadsheet'])]
 add(slug,title,['Finance'],tags,q,m,result,limit,links,role='Historical course case study' if i!=8 else 'Team course project · Undral Ganbaatar, Shazil Farukh & Anne Behme',chart=chart)
finance(1,'wrigley','Wrigley: the price of leverage',['Capital structure','APV','WACC','Sensitivity analysis'],'Does a $3 billion debt-funded payout create value once financial distress enters the picture?','Compared tax-shield value, post-recapitalization borrowing costs, interest coverage and expected distress costs. Examined dividends versus repurchases and the difference between EPS mechanics and shareholder value.','The report’s no-distress tax shield is $1.2 billion. Its B-rated base scenario reduces net value creation to $732 million; a higher conditional distress loss reduces it to $576 million. The recommendation is sensitive to the debt capacity and distress assumptions.','The linked report is labeled a working draft. Values are case-model estimates, not realized outcomes; the distress scenarios depend on assumed conditional losses.', [('Tax shield before distress',1200),('Net value: base scenario',732),('Net value: higher loss',576)])
finance(8,'coreweave','CoreWeave: valuing capital-intensive AI',['DCF','Valuation','Comparables','Sensitivity analysis'],'How much of a fast-growing infrastructure company’s valuation depends on distant cash flows?','The team combined a DCF, public comparables and precedent transactions, with sensitivity analysis around financing costs, terminal growth, investment and working capital.','The April 2025 report presents a $10-per-share base DCF estimate and a $22 synthesis across methods. The important analytical issue is the spread between methods and the sensitivity to long-run assumptions.','This is a dated team case analysis, not a current price target. Segment-based comparables and terminal-value assumptions require particular care.')
finance(0,'toyota','Toyota: financial policy across borders',['Global finance','Ratio analysis','Currency exposure'],'How do production location, liquidity and currency exposure shape financial policy?','Compared Toyota’s financial ratios with automaker peers, then examined domestic production, international competitiveness and financial policy in the case’s 2010–2011 setting.','The case connects balance-sheet decisions to operating geography. A consolidated ratio alone can obscure the different funding needs of manufacturing and financial services.','Historical peer comparisons depend on consistent segment definitions. The case is not a statement about Toyota’s current financial position.')
finance(2,'aditya-birla','Aditya Birla: allocating capital internationally',['DCF','Capital allocation','Global finance'],'Which international investments fit a diversified group’s existing capabilities?','Developed an India–UAE SME payments and working-capital proposal and an UltraTech investment proposal. Built parent-level cash-flow forecasts, ownership adjustments and valuation scenarios.','The base models produce positive parent NPVs for both proposals. Their attractiveness depends on execution, volume, terminal value and the group’s ability to apply existing capabilities.','These are proposed investments and assumption-based forecasts, not projects implemented by the company.')
finance(3,'astral','Astral Records: growth needs financing',['Financial forecasting','Working capital','Capital budgeting'],'Can a growing company fund expansion while margins weaken?','Reviewed historical profitability and leverage, then forecast 1994–1995 financial statements with and without capital expenditure. Connected operating performance to financing requirements.','Revenue growth alone does not answer the funding question. The case brings margin pressure, debt servicing and capital spending into the same forecast.','Historical classroom case; projections depend on the case inputs and operating assumptions.')
finance(4,'science-technology','Science Technology: growth versus cash',['Financial forecasting','Working capital','Scenario analysis'],'What must improve for a 30% growth plan to be financeable?','Examined a plan that accelerates sales growth beyond the historical rate. Reconstructed the cash conversion cycle, working-capital needs and reliance on short-term borrowing.','The forecast illustrates how rising accounting income can coexist with cash pressure. Inventory and receivables become central to the credibility of the growth plan.','Forecast improvements in inventory management are assumptions, not observed achievements.')
finance(5,'rvd-ai','RVD.AI: financing an early-stage venture',['Venture valuation','TAM','Dilution','Scenario analysis'],'How does the size of an initial investment change the ownership bargain?','Built a market-sizing and revenue scenario, applied a venture-capital valuation method and compared $2.5 million and $3.5 million funding cases. Examined sensitivity to market share and required returns.','In the report’s fixed post-money valuation scenario, larger funding sharply increases the investor’s ownership requirement. The case makes the growth-versus-dilution tradeoff explicit.','Market share, exit multiples and future margins are scenario assumptions. This is a historical academic analysis, not a completed financing.')
finance(6,'optiguard','Optiguard: what a term sheet changes',['Venture finance','Cap tables','Liquidation preferences'],'Why can two financing offers with similar headline valuations produce different outcomes?','Modeled ownership and option reserves, a hypothetical Series B, antidilution adjustments and conventional versus participating liquidation preferences.','Valuation is only one part of the bargain. Exit payouts, dilution and control provisions change the economics for founders and investors.','Hypothetical case scenarios; the analysis does not describe an executed investment.')
finance(7,'freddo','Freddo: growth under inflation',['Working capital','Expansion strategy','Scenario analysis'],'How can an expanding business manage cash when inflation and shipping complicate the cycle?','Examined receivables, inventory and payables, then developed operational and expansion scenarios including local production and changes in payment terms.','The proposal connects expansion with cash discipline: faster collections and shorter inventory cycles can matter as much as new locations.','Shipping costs, target cash-cycle days and expansion benefits are estimates. They are not verified cost savings or realized outcomes.')
(P/'projects.json').write_text(json.dumps(projects,ensure_ascii=False,indent=2))
