def shell(title,body,root=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Undral Ganbaatar</title><meta name="description" content="Research, finance and software projects by Undral Ganbaatar."><link rel="stylesheet" href="{root}style.css?v=2"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='6' fill='%23087d89'/%3E%3Ctext x='5' y='23' font-size='21' fill='white'%3EU%3C/text%3E%3C/svg%3E"></head><body><header><a href="{root or './'}"><strong>Undral Ganbaatar</strong></a><nav><a href="{root or './'}#projects">Projects</a><a href="https://github.com/undralg">GitHub</a></nav></header><main>{body}</main><footer>Undral Ganbaatar · Research, finance &amp; software · 2026</footer></body></html>'''
def tags(p):return '<div class="tags">'+''.join('<a class="tag" href="/?tag='+quote(t)+'#projects" title="Show all projects tagged '+E(t)+'">'+E(t)+'</a>' for t in p['tags'])+'</div>'
body='''<section class="hero"><div class="eyebrow">Research · Finance · Software</div><h1>Questions first.<br>Models with a purpose.</h1><p class="lead">I investigate how systems behave, build tools to explore them, and turn evidence into a clear argument.</p><p>Selected work in statistical inference, business decisions and software—from DNA relationships to a Mongolian card game.</p></section><section aria-labelledby="featured-title"><div class="section-head"><h2 id="featured-title">Featured work</h2><div class="controls"><button type="button" id="previous" aria-label="Previous featured project">Previous</button><button type="button" id="next" aria-label="Next featured project">Next</button></div></div><div class="featured" id="featured" tabindex="0" aria-label="Featured projects, scroll horizontally">'''
for p in projects[:3]:
 body+=f'<article class="feature-card"><div class="eyebrow">{E(p["category"][0])}</div><h3>{E(p["title"])}</h3><div class="metric">{E(p["metric"])}</div><div class="metric-label">{E(p["label"])}</div><p>{E(p["question"])}</p><a href="{p["slug"]}/">Explore project</a></article>'
body+='''</div></section><section id="projects" aria-labelledby="all-title"><h2 id="all-title">Explore all projects</h2><label class="search-label" for="project-search">Search projects, skills &amp; keywords</label><div class="search-row"><input type="search" id="project-search" placeholder="Try SQL, valuation, Bayesian or transcription" aria-describedby="search-help"><button type="button" id="clear-search">Clear search</button></div><p class="count" id="search-help">Search combines with the category below. Multiple words narrow the results.</p><div class="filters" role="group" aria-label="Filter projects by topic">'''
for c in ['All','Statistics & ML','Finance','Market Research','Software & AI']:
 body+=f'<button type="button" data-filter="{E(c)}" aria-pressed="{str(c=="All").lower()}">{E(c)}</button>'
body+=f'</div><p class="count" id="count" aria-live="polite">{len(projects)} projects</p><div class="grid">'
for p in projects:
 body+=f'<article class="card" data-tags="{E(json.dumps(p["tags"]))}" data-search="{E(" ".join([p["title"], *p["category"], *p["tags"], p["question"], p["method"], p["finding"]]))}" data-category="{E("|".join(p["category"]))}"><div class="eyebrow">{E(p["category"][0])}</div><h3><a href="{p["slug"]}/">{E(p["title"])}</a></h3><p>{E(p["question"])}</p>{tags(p)}<a class="visit" href="{p["slug"]}/">View project</a></article>'
body+='</div><p id="empty" hidden>No matching projects. Try a broader keyword or choose All.</p></section><script src="portfolio.js?v=4"></script>'
(P/'index.html').write_text(shell('Research portfolio',body))
