  for i,img in enumerate(slides,1):
   deck+=f'<figure style="flex:0 0 100%;min-width:0;margin:0;scroll-snap-align:start"><img src="../assets/abc-slides/{img.name}" alt="ABC research presentation, slide {i} of {len(slides)}" width="1600" height="900" loading="{"eager" if i==1 else "lazy"}" style="display:block;width:100%;height:auto"><figcaption style="padding:8px 16px;font-size:14px">Slide {i} of {len(slides)}</figcaption></figure>'
  deck+='</div><p><a href="../assets/ABC-presentation.pdf">Open or download the full PDF</a></p></section><script src="../slides.js"></script>'
