(P/'portfolio.js').write_text("""const cards=[...document.querySelectorAll('.card')];const filters=[...document.querySelectorAll('[data-filter]')];const input=document.getElementById('project-search');let selected='All';let activeTag=new URLSearchParams(location.search).get('tag')||'';input.value=activeTag;const normalize=s=>s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'');function update(){const terms=normalize(input.value).trim().split(/\s+/).filter(Boolean);let count=0;cards.forEach(card=>{const category=selected==='All'||card.dataset.category.split('|').includes(selected);const text=normalize(card.dataset.search);const tagMatch=!activeTag||JSON.parse(card.dataset.tags).some(t=>normalize(t)===normalize(activeTag));card.hidden=!category||!tagMatch||(!activeTag&&!terms.every(t=>text.includes(t)));if(!card.hidden)count++});document.getElementById('count').textContent=count+' of '+cards.length+' projects';document.getElementById('empty').hidden=count!==0}filters.forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.filter;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));update()}));function clearTag(){activeTag='';history.replaceState(null,'',location.pathname+location.hash)}input.addEventListener('input',()=>{clearTag();update()});document.getElementById('clear-search').addEventListener('click',()=>{input.value='';clearTag();update();input.focus()});document.querySelectorAll('.tag').forEach(link=>link.addEventListener('click',event=>{if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();activeTag=new URL(link.href).searchParams.get('tag')||'';input.value=activeTag;selected='All';filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='All')));history.pushState(null,'',link.href);update()}));window.addEventListener('popstate',()=>{activeTag=new URLSearchParams(location.search).get('tag')||'';input.value=activeTag;selected='All';filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='All')));update()});const rail=document.getElementById('featured');const reduced=matchMedia('(prefers-reduced-motion: reduce)');function move(direction){rail.scrollBy({left:direction*(rail.querySelector('article').getBoundingClientRect().width+24),behavior:reduced.matches?'auto':'smooth'})}document.getElementById('next').addEventListener('click',()=>move(1));document.getElementById('previous').addEventListener('click',()=>move(-1));function edges(){document.getElementById('previous').disabled=rail.scrollLeft<2;document.getElementById('next').disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2}rail.addEventListener('scroll',edges);window.addEventListener('resize',edges);edges();update();""")
